// Deck editor: reserve drops add one; dropping a deck group outside removes that kind.
S.deckSets=Array.from({length:5},(_,i)=>Array.isArray(S.deckSets?.[i])?S.deckSets[i]:null);
S.deckSetMeta=Array.from({length:5},(_,i)=>S.deckSetMeta?.[i]||{name:'SET '+(i+1),relicId:null});
function presetEscape(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function renameDeckSet(i,name){if(S.run||i<0||i>=5)return;S.deckSetMeta[i].name=name.trim().slice(0,40)||'SET '+(i+1);save()}
function presetDetails(i){return S.deckSets[i]?`<button class="preset-view-button" onclick="openPresetDetails(${i})">中身を見る</button>`:''}
function presetDialogContent(i){let ids=S.deckSets[i],meta=S.deckSetMeta[i],relic=S.relicVault?.find(x=>x.id===meta.relicId);return `<div class="preset-dialog-head"><div><div class="eyebrow">MY SET</div><h2 id="preset-dialog-title">${presetEscape(meta.name)}</h2></div><button autofocus onclick="this.closest('dialog').close()" aria-label="マイセットの詳細を閉じる">閉じる ×</button></div><div class="preset-dialog-body"><section><h3>保存した遺物</h3>${relic?relicPanel(relic):`<p class="tile">${meta.relicId?'保存した遺物は分解済みです。':'遺物は登録されていません。'}</p>`}</section><section><h3>デッキ内容 <small>${ids.length}枚 ／ ${new Set(ids).size}種類</small></h3><div class="cards preset-card-grid">${[...new Set(ids)].sort(cardOrder).map(id=>card(id,'',`<span class="preset-card-count">× ${ids.filter(x=>x===id).length}枚</span>`)).join('')||'<p class="tile">カードは登録されていません。</p>'}</div></section></div>`}
function openPresetDetails(i){if(!Number.isInteger(i)||!S.deckSets[i]||S.run)return;document.getElementById('preset-dialog')?.remove();let dialog=document.createElement('dialog');dialog.id='preset-dialog';dialog.className='preset-dialog';dialog.setAttribute('aria-labelledby','preset-dialog-title');dialog.innerHTML=presetDialogContent(i);dialog.addEventListener('pointerdown',e=>e.stopPropagation());dialog.addEventListener('click',e=>{if(e.target===dialog){let box=dialog.getBoundingClientRect();if(e.clientX<box.left||e.clientX>box.right||e.clientY<box.top||e.clientY>box.bottom)dialog.close()}});dialog.addEventListener('close',()=>dialog.remove(),{once:true});document.body.append(dialog);dialog.showModal()}

function deckStats(ids){let bins=[0,0,0,0,0],sum=0;for(let id of ids){let cost=C[id].cost;sum+=cost;bins[Math.min(4,cost)]++}let top=Math.max(1,...bins);return `<section class="deck-stats" aria-label="デッキのコスト分析"><div class="cost-average"><span>平均コスト</span><strong>${ids.length?(sum/ids.length).toFixed(1):'—'}</strong><small>${ids.length}枚のデッキ</small></div><div class="cost-distribution"><h3>コスト分布</h3><div class="cost-columns">${bins.map((n,i)=>`<div class="cost-column" aria-label="${i===4?'4以上':i}コスト ${n}枚"><b>${n}<small>枚</small></b><div class="cost-track"><i style="height:${n/top*100}%"></i></div><span>${i===4?'4+':i}</span></div>`).join('')}</div></div></section>`}
function saveDeckSet(i){if(S.run||i<0||i>=5)return;S.deckSets[i]=[...S.deck];S.deckSetMeta[i].relicId=S.equippedRelicId||null;render();toast(`マイセット ${i+1} に保存しました`)}
function loadDeckSet(i){if(S.run||!Array.isArray(S.deckSets[i]))return;let ids=S.deckSets[i],counts={};for(let id of ids){counts[id]=(counts[id]||0)+1;if(!C[id]||C[id].retired||C[id].runOnly||counts[id]>3||counts[id]>(S.collection[id]||0))return toast('現在の所持カードではこのマイセットを読み込めません')}if(ids.length>20)return;let relicId=S.deckSetMeta[i].relicId,missing=relicId&&!S.relicVault.some(x=>x.id===relicId);S.equippedRelicId=missing?null:relicId;S.deck=[...ids];render();if(missing)return toast('デッキを読み込みました。保存した遺物は分解済みのため未装備です');toast(`マイセット ${i+1} を読み込みました`)}
let deckResetPending=false;
function resetDeck(){if(S.run||!S.deck.length)return;deckResetPending=true;render()}
function confirmResetDeck(){if(S.run||!deckResetPending)return;deckResetPending=false;S.deck=[];render();toast('すべてのカードを未使用に戻しました')}
function cancelResetDeck(){deckResetPending=false;render()}
function removeDeckKind(id){if(S.run)return;S.deck=S.deck.filter(x=>x!==id);render()}
changeDeck=function(from,to,id){if(S.run||from===to||!C[id])return false;if(from==='reserve'&&to==='deck'){if(C[id].retired||C[id].runOnly)return false;if(S.deck.length>=20){toast('デッキの上限は20枚です');return false}if(count(id)>=3){toast('同じカードは3枚までです');return false}if(count(id)>=(S.collection[id]||0))return false;S.deck.push(id)}else if(from==='deck'&&to==='reserve'){let i=S.deck.indexOf(id);if(i<0)return false;S.deck.splice(i,1)}else return false;render();return true};
function addDeckKind(id){if(S.run||!C[id]||C[id].retired||C[id].runOnly)return false;const n=Math.max(0,Math.min((S.collection[id]||0)-count(id),3-count(id),20-S.deck.length));if(!n){toast('追加できる未使用カードがないか、デッキの上限に達しています');return false}S.deck.push(...Array(n).fill(id));render();return true}
edit=function(id,n){return n>0?changeDeck('reserve','deck',id):changeDeck('deck','reserve',id)};
const deckBeforeTools=deck;deck=function(){if(S.run)return deckBeforeTools()+deckStats(S.run.deck);let spare=C.filter(c=>!c.retired&&!c.runOnly&&(S.collection[c.id]||0)>count(c.id)).map(c=>c.id).sort(cardOrder),spareCount=spare.reduce((n,id)=>n+S.collection[id]-count(id),0);return `<div class="eyebrow">YOUR ARSENAL</div><h2>デッキの編成</h2><p>カードをタップ（クリック）すると1枚ずつ追加・取り外しできます。<br>未使用カードをデッキへドラッグすると、同名の未使用カードをまとめて追加（同名3枚・合計20枚の上限まで）。デッキの外へドラッグすると同じカードをすべて外します。<br>右クリックは1枚ずつ追加・取り外し。カード同士の交換は行いません。</p><div class="deck-info"><b>${S.deck.length} / 20 枚</b><span>同じカード3枚まで・出撃には10枚以上</span><button class="primary" onclick="start()" ${S.deck.length<10?'disabled':''}>このデッキで出発 →</button></div>${deckStats(S.deck)}<section class="deck-presets"><h3>マイセット <small>このブラウザに保存</small></h3><div class="preset-grid">${S.deckSets.map((ids,i)=>`<div class="preset-slot"><input class="preset-name" aria-label="マイセット${i+1}の名前" maxlength="40" value="${presetEscape(S.deckSetMeta[i].name)}" onchange="renameDeckSet(${i},this.value)"><span>${ids===null?'未保存':ids.length+'枚・平均 '+(ids.length?(ids.reduce((n,id)=>n+(C[id]?.cost||0),0)/ids.length).toFixed(1):'—')}</span><div><button onclick="saveDeckSet(${i})">${ids===null?'保存':'上書き保存'}</button><button onclick="loadDeckSet(${i})" ${ids===null?'disabled':''}>読込</button><button onclick="deleteDeckSet(${i})" ${ids===null?'disabled':''}>削除</button></div>${presetDetails(i)}</div>`).join('')}</div></section><div class="section-head"><h3>使用するデッキ</h3><button class="deck-reset" onclick="resetDeck()" ${S.deck.length?'':'disabled'}>デッキリセット</button></div><div class="cards deck-zone" data-drop="deck">${[...new Set(S.deck)].sort(cardOrder).map(id=>deckSlot(id,S.deck.indexOf(id),'deck')).join('')||'<p class="empty-deck">未使用カードをタップ、またはここへドラッグして追加<br><small>現在0枚・出撃には10枚以上必要です</small></p>'}</div><div class="section-head"><h3>未使用のカード</h3><span class="muted">${spareCount}枚</span></div><div class="cards deck-zone reserve" data-drop="reserve">${spare.map(id=>deckSlot(id,0,'reserve')).join('')||'<p>未使用のカードはありません。</p>'}</div>`};

